	tb.Helper()

	ctx := context.Background()
	dataDir := tb.TempDir()
	testProfile := getBenchmarkProfile(dataDir)
	dbDriver, err := db.NewDBDriver(testProfile)
	if err != nil {
		tb.Fatalf("failed to create db driver: %v", err)
	}

	testStore := store.New(dbDriver, testProfile)
	if err := testStore.Migrate(ctx); err != nil {
		tb.Fatalf("failed to migrate db: %v", err)
	}
	tb.Cleanup(func() {
		testStore.Close()
	})

	service := newServiceWithProfile(testProfile, testStore)
	return &TestService{
		Service: service,
		Store:   testStore,
		Profile: testProfile,
		Secret:  service.Secret,
	}
}

func prepareV0262MigrationTest(t *testing.T, driver string) (MemosContainerConfig, string) {
	t.Helper()

	const version = "0.26.2"

	switch driver {
	case "sqlite":
		dataDir := t.TempDir()
		return MemosContainerConfig{
			Version: version,
			Driver:  driver,
			DataDir: dataDir,
		}, fmt.Sprintf("%s/memos_prod.db", dataDir)
	case "mysql":
