		require.NoError(t, err)
		return MemosContainerConfig{
			Version: version,
			Driver:  driver,
			DSN:     containerDSN,
		}, hostDSN
	default:
		t.Fatalf("unsupported driver: %s", driver)
		return MemosContainerConfig{}, ""
	}
